SELECT
    (SELECT COALESCE(SUM(market_count + enterprise_count + intl_count), 0)
        FROM commodity WHERE status = 1

            AND varieties_id IN
            #{vid}

    ) AS totalCount,


            (SELECT COUNT(*) FROM commodity WHERE status=1)


            (SELECT COUNT(DISTINCT dp.varieties_id) FROM data_permission dp
                INNER JOIN commodity c ON c.varieties_id = dp.varieties_id AND c.status = 1
                WHERE dp.user_id = #{userId}
                AND (dp.expire_date IS NULL OR dp.expire_date >= CURDATE()))


    AS varietiesCount,
    (SELECT MAX(latest_date) FROM commodity WHERE status = 1

            AND varieties_id IN
            #{vid}

    ) AS latestDate,
    (SELECT COALESCE(SUM(market_count), 0) FROM commodity WHERE status = 1

            AND varieties_id IN
            #{vid}

    ) AS marketCount,
    (SELECT COALESCE(SUM(enterprise_count), 0) FROM commodity WHERE status = 1

            AND varieties_id IN
            #{vid}

    ) AS enterpriseCount,
    (SELECT COALESCE(SUM(intl_count), 0) FROM commodity WHERE status = 1

            AND varieties_id IN
            #{vid}

    ) AS intlCount

SELECT COUNT(*) AS totalCount, SUM(CASE WHEN data_rise_or_fall > 0 THEN 1 ELSE 0 END) AS upCount, SUM(CASE WHEN data_rise_or_fall = 0 OR data_rise_or_fall IS NULL THEN 1 ELSE 0 END) AS flatCount, SUM(CASE WHEN data_rise_or_fall < 0 THEN 1 ELSE 0 END) AS downCount FROM market_price WHERE data_date = (
SELECT data_date FROM market_price WHERE middle_price IS NOT NULL ORDER BY data_date DESC LIMIT 1 ) AND middle_price IS NOT NULL
AND varieties_id IN #{vid}

SELECT COUNT(*) FROM

        enterprise_price
        international_price
        market_price

WHERE middle_price IS NOT NULL

    AND varieties_id IN

        #{vid}


AND market_name = #{marketName}
AND data_date >= #{startDate}
AND data_date <= #{endDate}

SELECT t.* FROM ( SELECT id, business_id, varieties_id, varieties_name, market_name, specifications_name, price_type_name, unit_valuation_name, region_name, brand_name, data_date, low_price, high_price, middle_price, rmb_price, NULL AS calc_rmb_price, NULL AS fx_used_currency, data_rise_or_fall, data_rate, remark, uid, fetched_at, 3 AS business_type FROM market_price WHERE middle_price IS NOT NULL UNION ALL SELECT id, business_id, varieties_id, varieties_name, market_name, specifications_name, price_type_name, unit_valuation_name, region_name, brand_name, data_date, low_price, high_price, middle_price, rmb_price, NULL AS calc_rmb_price, NULL AS fx_used_currency, data_rise_or_fall, data_rate, remark, uid, fetched_at, 2 AS business_type FROM enterprise_price WHERE middle_price IS NOT NULL UNION ALL SELECT id, business_id, varieties_id, varieties_name, market_name, specifications_name, price_type_name, unit_valuation_name, region_name, brand_name, data_date, low_price, high_price, middle_price, rmb_price, calc_rmb_price, fx_used_currency, data_rise_or_fall, data_rate, remark, uid, fetched_at, 4 AS business_type FROM international_price WHERE middle_price IS NOT NULL ) t
AND t.varieties_id IN
#{vid}
AND t.market_name = #{marketName} AND t.data_date >= #{startDate} AND t.data_date <= #{endDate}
ORDER BY t.data_date DESC, t.varieties_id, t.id LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM ( SELECT id, business_id, varieties_id, varieties_name, market_name, specifications_name, price_type_name, unit_valuation_name, region_name, brand_name, data_date, low_price, high_price, middle_price, rmb_price, NULL AS calc_rmb_price, NULL AS fx_used_currency, data_rise_or_fall, data_rate, remark, uid, fetched_at, 3 AS business_type FROM market_price WHERE middle_price IS NOT NULL UNION ALL SELECT id, business_id, varieties_id, varieties_name, market_name, specifications_name, price_type_name, unit_valuation_name, region_name, brand_name, data_date, low_price, high_price, middle_price, rmb_price, NULL AS calc_rmb_price, NULL AS fx_used_currency, data_rise_or_fall, data_rate, remark, uid, fetched_at, 2 AS business_type FROM enterprise_price WHERE middle_price IS NOT NULL UNION ALL SELECT id, business_id, varieties_id, varieties_name, market_name, specifications_name, price_type_name, unit_valuation_name, region_name, brand_name, data_date, low_price, high_price, middle_price, rmb_price, calc_rmb_price, fx_used_currency, data_rise_or_fall, data_rate, remark, uid, fetched_at, 4 AS business_type FROM international_price WHERE middle_price IS NOT NULL ) t
AND t.varieties_id IN
#{vid}
AND t.market_name = #{marketName} AND t.data_date >= #{startDate} AND t.data_date <= #{endDate}
